import type { FastifyInstance } from "fastify";
import { auth } from "@/lib/auth";

/**
 * Better Auth Route Handler
 * 
 * Registers all Better Auth endpoints at /api/auth/*
 * Better Auth handles:
 * - POST /api/auth/sign-up - Email/password registration
 * - POST /api/auth/sign-in - Email/password login
 * - POST /api/auth/sign-out - Logout
 * - GET /api/auth/session - Get current session
 * - And many more...
 * 
 * See: https://better-auth.com/docs/reference/client-side-methods
 */
export default async function authRoutes(fastify: FastifyInstance) {
  // Handle all Better Auth requests
  fastify.all<{ Params: { "*": string } }>("/api/auth/*", async (request, reply) => {
    // Build the full path for Better Auth
    const path = "/" + (request.params["*"] || "");

    // Create a fetch-compatible request for Better Auth handler
    const url = new URL(
      `${request.protocol}://${request.hostname}${request.url}`
    );

    try {
      const response = await auth.handler(
        new Request(url, {
          method: request.method,
          headers: request.headers as HeadersInit,
          body:
            request.method !== "GET" && request.method !== "HEAD"
              ? JSON.stringify(request.body)
              : undefined,
        })
      );

      // Set response headers
      response.headers.forEach((value, key) => {
        reply.header(key, value);
      });

      // Send response
      reply.code(response.status);
      return reply.send(await response.text());
    } catch (error) {
      fastify.log.error(error);
      return reply.code(500).send({ error: "Internal server error" });
    }
  });
}

